/**
 * Concatenates the emitter's one-module-per-type output into a single ES module.
 * Generated modules share a deterministic name mapping, so their top-level bindings
 * can live in one scope; only the per-module runtime and sibling imports need merging.
 *
 * `$class` resolves `base()` and `interfaces()` immediately, so bundle order must put
 * dependencies (interfaces, then base classes) before their dependents.
 */
import type { SourceMapping } from "./sourcemap.ts";

interface BodyLine {
  text: string;
  originalLine: number | null;
}

interface BundleModule {
  file: string;
  name: string;
  body: BodyLine[];
  dependencies: Set<string>;
}

export interface BundleResult {
  text: string;
  mappings: SourceMapping[];
}

function dependencyNames(trimmed: string): string[] {
  const base = trimmed.match(/^base: \(\) => ([A-Za-z_$][A-Za-z0-9_$]*),?$/);
  if (base) return [base[1]!];
  const list = trimmed.match(/^(?:interfaces|extends): \(\) => \[(.*)\],?$/);
  if (!list) return [];
  return list[1]!
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);
}

export function bundleModules(
  files: Map<string, string>,
  runtimeSpecifier: string,
  sourceMappings?: ReadonlyMap<string, SourceMapping[]>,
): BundleResult {
  const helpers = new Set<string>();
  const exports = new Set<string>();
  const externalDecls = new Set<string>();
  const modules: BundleModule[] = [];
  const runtimeSuffix = ` from ${JSON.stringify(runtimeSpecifier)};`;

  for (const file of [...files.keys()].filter((item) => item !== "index.mjs").sort()) {
    const source = files.get(file)!;
    const body: BodyLine[] = [];
    const dependencies = new Set<string>();
    let exportName: string | null = null;
    source.split("\n").forEach((line, index) => {
      const trimmed = line.trim();
      if (trimmed.startsWith("//# sourceMappingURL=")) return;
      if (trimmed.startsWith("import {") && trimmed.endsWith(runtimeSuffix)) {
        const inner = trimmed.slice("import {".length, trimmed.lastIndexOf("}")).trim();
        for (const helper of inner.split(",")) {
          if (helper.trim()) helpers.add(helper.trim());
        }
        return;
      }
      if (trimmed.startsWith("import {")) return;
      if (trimmed.startsWith("const __rt_")) {
        externalDecls.add(trimmed);
        return;
      }
      const exported = trimmed.match(/^export const ([A-Za-z_$][A-Za-z0-9_$]*) = /);
      if (exported) {
        exportName = exported[1]!;
        exports.add(exportName);
        body.push({ text: trimmed.replace(/^export /, ""), originalLine: index + 1 });
        return;
      }
      for (const dependency of dependencyNames(trimmed)) dependencies.add(dependency);
      body.push({ text: line, originalLine: index + 1 });
    });
    if (exportName) modules.push({ file, name: exportName, body, dependencies });
  }

  const byName = new Map(modules.map((module) => [module.name, module]));
  const ordered: BundleModule[] = [];
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const visit = (module: BundleModule): void => {
    if (visited.has(module.name) || visiting.has(module.name)) return;
    visiting.add(module.name);
    for (const dependency of [...module.dependencies].sort()) {
      const target = byName.get(dependency);
      if (target) visit(target);
    }
    visiting.delete(module.name);
    visited.add(module.name);
    ordered.push(module);
  };
  for (const module of modules) visit(module);

  const out: string[] = ["// Generated by as3js: single-file ES module bundle."];
  if (helpers.size > 0) {
    out.push(`import { ${[...helpers].sort().join(", ")} } from ${JSON.stringify(runtimeSpecifier)};`);
    out.push("");
  }
  if (externalDecls.size > 0) {
    out.push(...[...externalDecls].sort());
    out.push("");
  }

  const mappings: SourceMapping[] = [];
  for (const module of ordered) {
    if (out.length > 0 && out[out.length - 1] !== "") out.push("");
    const startLine = out.length + 1;
    const byOriginalLine = new Map<number, number>();
    module.body.forEach((line, index) => {
      if (line.originalLine !== null) byOriginalLine.set(line.originalLine, index);
    });
    for (const mapping of sourceMappings?.get(module.file) ?? []) {
      const index = byOriginalLine.get(mapping.generatedLine);
      if (index === undefined) continue;
      mappings.push({ ...mapping, generatedLine: startLine + index });
    }
    out.push(...module.body.map((line) => line.text));
  }

  if (out[out.length - 1] !== "") out.push("");
  if (exports.size > 0) out.push(`export { ${[...exports].sort().join(", ")} };`);
  return { text: `${out.join("\n")}\n`, mappings };
}
